@EventRepresentation('objectarray') @public @buseventtype @public create schema MyEvent as (name string, value double);
@EventRepresentation('objectarray') @public create window MyInfraIOS#unique(name) as MyEvent;
insert into MyInfraIOS select * from MyEvent;
@EventRepresentation('objectarray') create schema InputEvent as (col1 string, col2 double);

on MyEvent as eme
  merge MyInfraIOS as MyInfraIOS where MyInfraIOS.name = eme.name
   when matched then
      insert into OtherStreamOne select eme.name as event_name, MyInfraIOS.value as status
   when not matched then
      insert into OtherStreamOne select eme.name as event_name, 0d as status;
@name('s0') select * from OtherStreamOne;

